const form = document.getElementById("predictionForm");
const carName = document.getElementById("Car_Name");
const predictBtn = document.getElementById("predictBtn");
const result = document.getElementById("result");
const price = document.getElementById("price");
const message = document.getElementById("message");
const errorBox = document.getElementById("error");

async function loadCarNames() {
  // The dataset values are embedded in a small API-free list generated by the
  // training dataset. This avoids adding a second backend endpoint.
  const names = [
    "800","Activa 3g","Activa 4g","Bajaj  ct 100","Bajaj Avenger 150",
    "Bajaj Avenger 150 street","Bajaj Avenger 220","Bajaj Avenger 220 dtsi",
    "Bajaj Avenger Street 220","Bajaj Discover 100","Bajaj Discover 125",
    "Bajaj Dominar 400","Bajaj Pulsar 135 ls","Bajaj Pulsar 150",
    "Bajaj Pulsar 220 F","Bajaj Pulsar NS 200","Bajaj Pulsar RS200",
    "Bajaj ct 100","Baleno","Brio","Camry","Ciaz","City","City 2017",
    "Classic 350","Corolla","Corolla Altis","Creta","Dzire","Eeco",
    "Eon","Ertiga","Etios Cross","Etios G","Etios GD","Etios Liva",
    "Figo","Fortuner","Grand i10","Honda CB Hornet 160R","Honda CB Shine",
    "Honda CB Trigger","Honda CB Twister","Honda CBR 150","Honda Dream Yuga",
    "Honda Karizma","Honda Karizma ZMR","Ignis","Innova","Jazz","KTM 390 Duke",
    "KTM RC200","KTM RC390","KTM RC390","Kwid","Land Cruiser","Maestro",
    "Mahindra Mojo 300","Mahindra Scorpio","Mahindra XUV500","Maruti Alto 800",
    "Maruti Baleno","Maruti Celerio","Maruti Celerio Green","Maruti Swift",
    "Maruti Swift Dzire","Maruti Wagon R","Mercedes-Benz B Class",
    "Mercedes-Benz GLA","Mercedes-Benz GLS","Nexon","Omni","Ritz",
    "Royal Enfield Bullet 350","Royal Enfield Classic","Royal Enfield Classic 350",
    "Royal Enfield Classic 500","Royal Enfield Thunder 350","S-Cross","Santro",
    "Santro Xing","Scala","Silverado","S-Presso","Thar","Tiago","Tigor",
    "TVS Apache RTR 160","TVS Apache RTR 180","TVS Apache RTR 200",
    "TVS Jupyter","TVS Sport","TVS Wego","UM Renegade Mojave","Verna",
    "Vento","Vitara Brezza","Wagon R","WR-V","Yamaha FZ  v 2.0","Yamaha FZ 16",
    "Yamaha FZ S","Yamaha FZ S V 2.0","Yamaha Fazer","Yamaha Fazer FI V 2.0",
    "Yamaha R15","Yamaha R15 V3","Yamaha Saluto","Yamaha Saluto RX",
    "alto 800","alto k10","amaze","baleno","brio","camry","ciaz","city",
    "city 2017","corolla","corolla altis","creta","dzire","elantra","ertiga",
    "etios cross","etios gd","etios g","etios liva","eon","fortuner","grand i10",
    "ignis","innova","jazz","land cruiser","kwid","omni","ritz","s cross",
    "swift","swift dzire","sx4","tiago","tigor","v40","verna","vitara brezza",
    "wagon r","xcent","xylo","zest","wagon r"
  ];

  const unique = [...new Set(names)].sort((a,b) => a.localeCompare(b));
  carName.innerHTML = unique.map(n => `<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>`).join("");
  if ([...carName.options].some(o => o.value === "swift")) carName.value = "swift";
}

function escapeHtml(value) {
  return value.replace(/[&<>"']/g, c => ({
    "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#039;"
  }[c]));
}

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  errorBox.hidden = true;
  result.hidden = true;
  predictBtn.disabled = true;
  predictBtn.textContent = "Predicting...";

  const payload = {
    Car_Name: carName.value,
    Year: document.getElementById("Year").value,
    Present_Price: document.getElementById("Present_Price").value,
    Driven_kms: document.getElementById("Driven_kms").value,
    Fuel_Type: document.getElementById("Fuel_Type").value,
    Selling_type: document.getElementById("Selling_type").value,
    Transmission: document.getElementById("Transmission").value,
    Owner: document.getElementById("Owner").value
  };

  try {
    const response = await fetch("/api/predict", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify(payload)
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || "Prediction failed.");

    price.textContent = `₹${Number(data.predicted_price).toFixed(2)} lakh`;
    message.textContent = data.message;
    result.hidden = false;
  } catch (err) {
    errorBox.textContent = err.message || "Something went wrong.";
    errorBox.hidden = false;
  } finally {
    predictBtn.disabled = false;
    predictBtn.textContent = "Predict selling price";
  }
});

loadCarNames();
